135	pub async fn serve_model_with_lora_routes(
136	    engine: crate::engine::Engine,
137	    model_id: impl Into<String>,
138	    served_model_name: Vec<String>,
139	    lora_modules: Vec<LoraModule>,
140	    port: u16,
141	    max_model_len: u32,
142	    shutdown: CancellationToken,
143	) -> Result<()> {
144	    let model_id = model_id.into();
145	    let adapter_names = Arc::new(RwLock::new(HashSet::new()));
146	    // The Option is the capability: only engines that minted a LoRA channel
147	    // can serve these routes.
148	    let control = engine
149	        .lora
150	        .clone()
151	        .ok_or_else(|| anyhow::anyhow!("engine does not expose LoRA adapter control"))?;
152	    load_startup_lora_modules(&control, &adapter_names, &lora_modules).await?;
153	    let base_model_name = served_model_name
154	        .first()
155	        .cloned()
156	        .unwrap_or_else(|| model_id.clone());
157	    serve_model_on_host_with_router_extension(
158	        std::future::ready(Ok(LaunchedEngine::Stepped(engine))),
159	        model_id,
160	        served_model_name.clone(),
161	        "0.0.0.0".to_string(),
162	        port,
163	        max_model_len,
164	        1,
165	        shutdown,
166	        move |router| {
167	            let lora_router = lora_routes(control, Arc::clone(&adapter_names));
168	            let openai_router = lora_openai_routes(
169	                router.clone(),
170	                base_model_name,
171	                served_model_name,
172	                Arc::clone(&adapter_names),
173	            );
174	            openai_router.merge(lora_router).fallback_service(router)
175	        },
176	    )
177	    .await
178	}
