204	async fn serve_model_on_host_with_router_extension<F>(
205	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
206	    model_id: String,
207	    served_model_name: Vec<String>,
208	    host: String,
209	    port: u16,
210	    max_model_len: u32,
211	    engine_count: usize,
212	    shutdown: CancellationToken,
213	    extend_router: F,
214	) -> Result<()>
215	where
216	    F: FnOnce(Router) -> Router,
217	{
218	    ensure!(engine_count > 0, "frontend engine_count must be positive");
219	    let data_parallel_size = u32::try_from(engine_count)
220	        .map_err(|_| anyhow::anyhow!("frontend engine_count {engine_count} exceeds u32"))?;
221	    let namespace = local_ipc_namespace()?;
222	    let input_address = ipc_endpoint(&namespace, "input.sock");
223	    let output_address = ipc_endpoint(&namespace, "output.sock");
224	
225	    // The HTTP server runs concurrently with the engine load: vllm-server
226	    // spends ~1s loading the tokenizer and chat templates before it waits for
227	    // an engine to register, so neither waits on the other. This task attaches
228	    // the bridge once the engine resolves and runs it to completion; on engine
229	    // failure it cancels the server so the error surfaces instead of hanging
230	    // in the registration wait.
231	    let server_shutdown = shutdown.child_token();
232	    let bridge_shutdown = shutdown.child_token();
233	    let engine_task = tokio::spawn({
234	        let server_shutdown = server_shutdown.clone();
235	        let bridge_shutdown = bridge_shutdown.clone();
236	        let input_address = input_address.clone();
237	        let output_address = output_address.clone();
238	        async move {
239	            let launched = match engine.await {
240	                Ok(launched) => launched,
241	                Err(error) => {
242	                    server_shutdown.cancel();
243	                    return Err(error);
244	                }
245	            };
246	            let mut bridges = tokio::task::JoinSet::new();
247	            // Stepped engines own their scheduler threads; reaped below after
248	            // the bridges (and with them the scheduler handles) are gone.
249	            let mut scheduler_joins: Vec<std::thread::JoinHandle<()>> = Vec::new();
250	            match launched {
251	                LaunchedEngine::Handle(handle) => {
252	                    let actual_partitions = handle.scheduler_partition_count();
253	                    if actual_partitions != engine_count {
254	                        server_shutdown.cancel();
255	                        anyhow::bail!(
256	                            "frontend declared {engine_count} engines but the resolved handle \
257	                             exposes {actual_partitions} scheduler partitions"
258	                        );
259	                    }
260	                    let servable_limit = handle.servable_len().map(|cap| max_model_len.min(cap));
261	                    let max_model_len = servable_limit.unwrap_or(max_model_len);
262	                    for engine_index in 0..engine_count {
263	                        let bridge = LocalEngineBridge {
264	                            input_address: input_address.clone(),
265	                            output_address: output_address.clone(),
266	                            handle: handle.clone(),
267	                            max_model_len,
268	                            engine_index: engine_index as u32,
269	                            data_parallel_size,
270	                            metrics_watch: handle.metrics_watch_for(engine_index),
271	                        };
272	                        let shutdown = bridge_shutdown.clone();
273	                        bridges.spawn(async move { (engine_index, bridge.run(shutdown).await) });
274	                    }
275	                    drop(handle);
276	                }
277	                LaunchedEngine::Stepped(engine) => {
278	                    let actual_schedulers = engine.schedulers.len();
279	                    if actual_schedulers != engine_count {
280	                        server_shutdown.cancel();
281	                        anyhow::bail!(
282	                            "frontend declared {engine_count} engines but the launched engine \
283	                             exposes {actual_schedulers} schedulers"
284	                        );
285	                    }
286	                    let info = engine.info;
287	                    let servable_limit = info.servable_len.map(|cap| max_model_len.min(cap));
288	                    let max_model_len = servable_limit.unwrap_or(max_model_len);
289	                    for (engine_index, scheduler) in engine.schedulers.into_iter().enumerate() {
290	                        scheduler_joins.push(scheduler.join);
291	                        let bridge = bridge::SteppedEngineBridge {
292	                            input_address: input_address.clone(),
293	                            output_address: output_address.clone(),
294	                            scheduler: scheduler.handle,
295	                            kv_capacity: info.kv_capacity,
296	                            max_model_len,
297	                            engine_index: engine_index as u32,
298	                            data_parallel_size,
299	                        };
300	                        let shutdown = bridge_shutdown.clone();
301	                        bridges.spawn(async move { (engine_index, bridge.run(shutdown).await) });
302	                    }
303	                }
304	            }
305	
306	            let mut bridge_error = None;
307	            while let Some(joined) = bridges.join_next().await {
308	                match joined {
309	                    Ok((_, Ok(()))) if bridge_shutdown.is_cancelled() => {}
310	                    Ok((engine_index, Ok(()))) => {
311	                        bridge_error = Some(anyhow::anyhow!(
312	                            "local vLLM engine {engine_index} bridge exited unexpectedly"
313	                        ));
314	                        break;
315	                    }
316	                    Ok((engine_index, Err(error))) => {
317	                        bridge_error = Some(
318	                            error
319	                                .context(format!("local vLLM engine {engine_index} bridge failed")),
320	                        );
321	                        break;
322	                    }
323	                    Err(error) => {
324	                        bridge_error = Some(anyhow::anyhow!(
325	                            "local vLLM engine bridge task panicked: {error}"
326	                        ));
327	                        break;
328	                    }
329	                }
330	            }
331	            if bridge_error.is_some() {
332	                server_shutdown.cancel();
333	                bridge_shutdown.cancel();
334	                bridges.abort_all();
335	                while bridges.join_next().await.is_some() {}
336	            }
337	            // The bridges are gone, and with them the partition handles:
338	            // submission channels are disconnected, so the drivers drain and
339	            // exit. Reap their threads to surface scheduler panics.
340	            if !scheduler_joins.is_empty() {
341	                let _ = tokio::task::spawn_blocking(move || {
342	                    for join in scheduler_joins {
343	                        if join.join().is_err() {
344	                            warn!("scheduler thread panicked during shutdown");
345	                        }
346	                    }
347	                })
348	                .await;
349	            }
350	            match bridge_error {
351	                Some(error) => Err(error),
352	                None => Ok(()),
353	            }
354	        }
355	    });
356	
357	    let config = Config {
358	        transport_mode: TransportMode::Bootstrapped {
359	            input_address,
360	            output_address,
361	            engine_start_index: 0,
362	            engine_count,
363	            data_parallel_size: engine_count,
364	            // The in-process bridge registers once the engine future resolves,
365	            // so this bounds the whole engine load (multi-GPU MoE models take
366	            // minutes, cold starts longer). Load *failure* already cancels the
367	            // server via the engine task; this only catches a truly hung load.
368	            ready_timeout: Duration::from_mins(30),
369	        },
370	        coordinator_mode: CoordinatorMode::None,
371	        model: model_id,
372	        generation_config: GenerationConfigMode::Auto,
373	        served_model_name,
374	        listener_mode: HttpListenerMode::BindTcp { host, port },
375	        tool_call_parser: ParserSelection::default(),
376	        reasoning_parser: ParserSelection::default(),
377	        renderer: RendererSelection::default(),
378	        chat_template: None,
379	        default_chat_template_kwargs: None,
380	        limit_mm_per_prompt: HashMap::new(),
381	        // Startup adapters go through the engine-side LoRA channel
382	        // (`load_startup_lora_modules`), never the upstream static loader.
383	        lora_modules: Vec::new(),
384	        chat_template_content_format: ChatTemplateContentFormatOption::default(),
385	        max_logprobs: None,
386	        language_model_only: true,
387	        cors: CorsConfig::default(),
388	        api_keys: Vec::new(),
389	        api_server_options: ApiServerOptions {
390	            enable_log_requests: true,
391	            enable_prompt_tokens_details: true,
392	            enable_request_id_headers: false,
393	        },
394	        disable_log_stats: true,
395	        grpc_port: None,
396	        shutdown_timeout: Duration::from_secs(10),
397	        keep_alive_timeout: DEFAULT_KEEP_ALIVE_TIMEOUT,
398	        profiler: None,
399	        tls: None,
400	    };
401	
402	    let result =
403	        vllm_server::serve_with_router_extension(config, server_shutdown, extend_router).await;
404	    // Stop the bridge (no-op if the caller's shutdown already cancelled it),
405	    // then collect the engine task. If the server failed while the engine is
406	    // still loading, the uncancellable blocking load must finish first.
407	    bridge_shutdown.cancel();
408	    if result.is_err() && !engine_task.is_finished() {
409	        warn!("HTTP server failed; waiting for the in-flight engine load to finish before exit");
410	    }
411	    let result = match engine_task.await {
412	        Ok(Ok(())) => result,
413	        // Engine failed: the server saw a cancel and returned Ok — the engine
414	        // error is the one worth reporting.
415	        Ok(Err(engine_error)) => result.and(Err(engine_error)),
416	        Err(join_error) => result.and(Err(anyhow::anyhow!(
417	            "engine startup task panicked: {join_error}"
418	        ))),
419	    };
420	    let _ = std::fs::remove_dir_all(namespace);
421	    result
422	}
423	
424	pub fn load_max_model_len(model_path: &Path) -> Option<u32> {
425	    let content = std::fs::read_to_string(model_path.join("config.json")).ok()?;
426	    serde_json::from_str::<ModelLenConfig>(&content)
427	        .ok()?
428	        .max_model_len()
429	}
430	
431	fn resolve_max_model_len(model_path: &Path, max_model_len: Option<u32>) -> u32 {
432	    max_model_len.unwrap_or_else(|| {
433	        load_max_model_len(model_path).unwrap_or_else(|| {
434	            const FALLBACK_MAX_MODEL_LEN: u32 = 4096;
435	            warn!(
436	                "max_position_embeddings not found in {}/config.json; capping max_model_len at {FALLBACK_MAX_MODEL_LEN}. \
437	                 Requests are limited to this length — set max_position_embeddings in the model config if it supports more.",
438	                model_path.display()
439	            );
440	            FALLBACK_MAX_MODEL_LEN
441	        })
442	    })
443	}
444	
445	/// Cancel `token` on the first CTRL+C. Installing the handler replaces the
446	/// default SIGINT kill behavior — only call this once whatever the token
447	/// guards can actually wind down (e.g. after an uncancellable blocking engine
448	/// load has finished), otherwise CTRL+C turns into a no-op wait.
449	pub fn cancel_token_on_ctrl_c(token: &CancellationToken) {
450	    let shutdown = token.clone();
451	    tokio::spawn(async move {
452	        if let Err(error) = tokio::signal::ctrl_c().await {
453	            warn!("failed to install CTRL+C handler: {error}");
454	        }
455	        shutdown.cancel();
456	    });
457	}
458	
459	pub fn shutdown_token_from_ctrl_c() -> CancellationToken {
460	    let token = CancellationToken::new();
461	    cancel_token_on_ctrl_c(&token);
462	    token
463	}
