19	pub(crate) fn to_wire_position_logprobs(
20	    token_id: u32,
21	    logprob: Option<TokenLogprob>,
22	) -> Option<PositionLogprobs> {
23	    let lp = logprob?;
24	    let mut entries = Vec::with_capacity(1 + lp.top_logprobs.len());
25	    entries.push(WireTokenLogprob {
26	        token_id,
27	        logprob: lp.logprob,
28	        rank: lp.rank,
29	    });
30	    for (index, (alt_id, alt_logprob)) in lp.top_logprobs.into_iter().enumerate() {
31	        if alt_id == token_id {
32	            continue;
33	        }
34	        entries.push(WireTokenLogprob {
35	            token_id: alt_id,
36	            logprob: alt_logprob,
37	            rank: (index + 1) as u32,
38	        });
39	    }
40	    Some(PositionLogprobs { entries })
41	}
