43	/// The engine includes the unscored leading token; vLLM restores it itself.
44	/// Never drop a missing scored position: every following offset would shift.
45	pub(crate) fn to_wire_prompt_logprobs(prompt: PromptEcho) -> Result<Option<MaybeWireLogprobs>> {
46	    ensure!(
47	        !prompt.ids.is_empty(),
48	        "prompt logprobs contain an empty prompt"
49	    );
50	    ensure!(
51	        prompt.ids.len() == prompt.logprobs.len(),
52	        "prompt logprobs length mismatch: {} tokens, {} scores",
53	        prompt.ids.len(),
54	        prompt.logprobs.len()
55	    );
56	    ensure!(
57	        prompt.logprobs[0].is_none(),
58	        "the first prompt token must have no logprob"
59	    );
60	    if prompt.ids.len() == 1 {
61	        return Ok(None);
62	    }
63	    let positions = prompt
64	        .ids
65	        .into_iter()
66	        .zip(prompt.logprobs)
67	        .enumerate()
68	        .skip(1)
69	        .map(|(index, (id, logprob))| {
70	            to_wire_position_logprobs(id, logprob)
71	                .with_context(|| format!("missing prompt logprob at position {index}"))
72	        })
73	        .collect::<Result<Vec<_>>>()?;
74	    Ok(Some(MaybeWireLogprobs::Direct(Logprobs { positions })))
75	}
