77	pub(crate) fn convert_sampling(params: &EngineCoreSamplingParams) -> SamplingParams {
78	    // The vLLM frontend lowers a client `ignore_eos=true` to `_eos_token_id:
79	    // None`, but `_all_stop_token_ids` always carries the model EOS set (it
80	    // exists for min_tokens masking, not stop detection). Deriving ignore_eos
81	    // from all_stop_token_ids would therefore void every ignore_eos request on
82	    // models with a real EOS. Only `_eos_token_id` and the client's explicit
83	    // `stop_token_ids` express a stop intent.
84	    let ignore_eos = params.eos_token_id.is_none() && params.stop_token_ids.is_empty();
85	    if params.temperature <= 0.0 {
86	        return SamplingParams {
87	            temperature: 0.0,
88	            top_k: -1,
89	            top_p: 1.0,
90	            min_p: 0.0,
91	            seed: None,
92	            ignore_eos,
93	        };
94	    }
95	
96	    SamplingParams {
97	        temperature: params.temperature,
98	        top_k: if params.top_k == 0 {
99	            -1
100	        } else {
101	            i32::try_from(params.top_k).unwrap_or(i32::MAX)
102	        },
103	        top_p: params.top_p,
104	        min_p: params.min_p,
105	        // Per-request seeds need the scheduler to feed request-local step
106	        // counts into select_batch; until that lands, seeded requests are
107	        // rejected in the bridge instead of silently ignored. See the
108	        // sampling-parity tracking issue.
109	        seed: None,
110	        ignore_eos,
111	    }
112	}
