114	/// Reject request parameters the engine would otherwise silently ignore.
115	/// Returns the offending description; `None` means the request is servable.
116	///
117	/// The float comparisons are exact on purpose: they detect "the client sent
118	/// anything other than the wire default", not numeric closeness — a request
119	/// carrying 1.0000001 wants a penalty and must be rejected, not rounded away.
120	#[allow(clippy::float_cmp)]
121	pub(crate) fn unsupported_request_params(params: &EngineCoreSamplingParams) -> Option<String> {
122	    // Engine-core clients may bypass HTTP validation; reject before converting to usize.
123	    if params.logprobs.is_some_and(|count| count < 0)
124	        || params.prompt_logprobs.is_some_and(|count| count < 0)
125	    {
126	        return Some("negative logprob counts are not supported".into());
127	    }
128	    if !(0.0..1.0).contains(&params.min_p) || !params.min_p.is_finite() {
129	        return Some(format!("min_p {} outside [0, 1)", params.min_p));
130	    }
131	    if params.temperature > 0.0 && params.seed.is_some() {
132	        return Some("per-request seed is not supported yet".to_string());
133	    }
134	    if params.frequency_penalty != 0.0 {
135	        return Some(format!(
136	            "frequency_penalty {} is not supported yet",
137	            params.frequency_penalty
138	        ));
139	    }
140	    if params.presence_penalty != 0.0 {
141	        return Some(format!(
142	            "presence_penalty {} is not supported yet",
143	            params.presence_penalty
144	        ));
145	    }
146	    if params.repetition_penalty != 1.0 {
147	        return Some(format!(
148	            "repetition_penalty {} is not supported yet",
149	            params.repetition_penalty
150	        ));
151	    }
152	    // The server lowers the client's ec_transfer_params into extra_args, and
153	    // this engine has no encoder cache connector to hand it to.
154	    if let Some(ec) = params
155	        .extra_args
156	        .as_ref()
157	        .and_then(|args| args.get("ec_transfer_params"))
158	    {
159	        let requested = match ec {
160	            serde_json::Value::Null => false,
161	            serde_json::Value::Object(map) => !map.is_empty(),
162	            _ => true,
163	        };
164	        if requested {
165	            return Some(
166	                "ec_transfer_params is not supported yet: this engine has no encoder cache \
167	                 connector"
168	                    .to_string(),
169	            );
170	        }
171	    }
172	    None
173	}
