74	    pub(crate) max_model_len: u32,
75	    pub(crate) engine_index: u32,
76	    pub(crate) data_parallel_size: u32,
77	    pub(crate) metrics_watch: Option<watch::Receiver<SchedulerMetrics>>,
78	}
