80	impl LocalEngineBridge {
81	    pub(crate) async fn run(self, shutdown: CancellationToken) -> Result<()> {
82	        let BridgeLink {
83	            mut input,
84	            output_tx,
85	            mut child_tasks,
86	        } = connect_link(
87	            &self.input_address,
88	            &self.output_address,
89	            self.engine_index,
90	            self.data_parallel_size,
91	            self.max_model_len,
92	            self.handle.kv_capacity(),
93	            self.metrics_watch.clone(),
94	            &shutdown,
95	        )
96	        .await?;
97	
98	        // One shared channel carries every request's token events, tagged by
99	        // request id; this loop is the sole consumer. Per-request state lives
100	        // in `streams`, keyed by the same tag, and holds the abort reason the
101	        // scheduler observes (via `TokenSink`) when an abort flips it.
102	        let (event_tx, mut event_rx) = mpsc::unbounded_channel();
103	        let mut streams: HashMap<RequestTag, RequestStreamState> = HashMap::new();
104	
105	        info!(
106	            "local vLLM engine {} bridge connected: input={}, output={}, max_model_len={}",
107	            self.engine_index, self.input_address, self.output_address, self.max_model_len
108	        );
109	
110	        let run_result = loop {
111	            tokio::select! {
112	                biased;
113	                () = shutdown.cancelled() => break Ok(()),
114	                joined = child_tasks.join_next(), if !child_tasks.is_empty() => {
115	                    if shutdown.is_cancelled() {
116	                        break Ok(());
117	                    }
118	                    break match joined {
119	                        Some(Ok((name, Ok(())))) => {
120	                            Err(anyhow::anyhow!("local engine {name} exited unexpectedly"))
121	                        }
122	                        Some(Ok((name, Err(error)))) => {
123	                            Err(error).with_context(|| format!("local engine {name} failed"))
124	                        }
125	                        Some(Err(error)) => {
126	                            Err(anyhow::anyhow!("local engine child task panicked: {error}"))
127	                        }
128	                        None => Err(anyhow::anyhow!("local engine child task set became empty")),
129	                    };
130	                }
131	                Some(first) = event_rx.recv() => {
132	                    if let Err(error) = dispatch_burst(
133	                        self.engine_index,
134	                        first,
135	                        &mut event_rx,
136	                        &mut streams,
137	                        &output_tx,
138	                    )
139	                    {
140	                        break Err(error).context("failed to dispatch local engine output");
141	                    }
142	                }
143	                recv = input.recv() => {
144	                    let message = match recv.context("failed to receive local engine request") {
145	                        Ok(message) => message,
146	                        Err(error) => break Err(error),
147	                    };
148	                    if let Err(error) = self.handle_message(
149	                        message,
150	                        &event_tx,
151	                        &output_tx,
152	                        &mut streams,
153	                    ) {
154	                        break Err(error).context("failed to handle local engine request");
155	                    }
156	                }
157	            }
158	        };
159	
160	        // Cancel every in-flight request so the scheduler retires them on its
161	        // next emit instead of pushing into a channel no one drains.
162	        for state in streams.values() {
163	            state.abort(RequestAbortReason::Cancelled);
164	        }
165	        drop(output_tx);
166	        child_tasks.abort_all();
167	        while child_tasks.join_next().await.is_some() {}
168	
169	        run_result
170	    }
171	
172	    fn handle_message(
173	        &self,
174	        message: ZmqMessage,
175	        event_tx: &mpsc::UnboundedSender<(RequestTag, TokenEvent)>,
176	        output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
177	        streams: &mut HashMap<RequestTag, RequestStreamState>,
178	    ) -> Result<()> {
179	        let frames = message.into_vec();
180	        if frames.len() != 2 {
181	            bail!(
182	                "expected 2 local engine request frames, got {}",
183	                frames.len()
184	            );
185	        }
186	
187	        match frames[0].as_ref() {
188	            ty if ty == EngineCoreRequestType::Add.to_frame().as_ref() => {
189	                let request: EngineCoreRequest =
190	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
191	                self.start_request(request, event_tx, output_tx, streams)
192	            }
193	            ty if ty == EngineCoreRequestType::Abort.to_frame().as_ref() => {
194	                let request_ids: Vec<String> =
195	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
196	                for request_id in request_ids {
197	                    // Drop our state first, then set the abort reason (so the
198	                    // scheduler's next emit fails and retires the request). The
199	                    // `Release` store orders the `streams.remove` before the
200	                    // reason the scheduler reads with `Acquire`; any token
201	                    // already in flight for this id is discarded by the demux
202	                    // when it finds no stream entry. An abort before the first
203	                    // token output reached the frontend is a disconnect; after
204	                    // that first token it is stream cancellation. Scheduled
205	                    // metadata can flush with the first engine output but is
206	                    // not enough to prove a client-visible token.
207	                    if let Some(state) = streams.remove(request_id.as_str()) {
208	                        let reason = if state.has_emitted_tokens {
209	                            RequestAbortReason::Cancelled
210	                        } else {
211	                            RequestAbortReason::Disconnected
212	                        };
213	                        state.abort(reason);
214	                    }
215	                }
216	                Ok(())
217	            }
218	            ty if ty == EngineCoreRequestType::Utility.to_frame().as_ref() => {
219	                let (_client_index, call_id, method_name, _args): (
220	                    u32,
221	                    UtilityCallId,
222	                    String,
223	                    rmpv::Value,
224	                ) = rmp_serde::from_slice(&frames[1])?;
225	                send_utility_response(self.engine_index, output_tx, call_id, &method_name)
226	            }
227	            other => bail!("unsupported local engine request type frame: {other:?}"),
228	        }
229	    }
230	
231	    fn start_request(
232	        &self,
233	        request: EngineCoreRequest,
234	        event_tx: &mpsc::UnboundedSender<(RequestTag, TokenEvent)>,
235	        output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
236	        streams: &mut HashMap<RequestTag, RequestStreamState>,
237	    ) -> Result<()> {
238	        let EngineCoreRequest {
239	            request_id,
240	            prompt_token_ids,
241	            sampling_params,
242	            ..
243	        } = request;
244	        let Some(prompt_tokens) = prompt_token_ids else {
245	            warn!("request {request_id} dropped: missing prompt_token_ids");
246	            send_terminal_output(
247	                self.engine_index,
248	                output_tx,
249	                request_id,
250	                EngineCoreFinishReason::Error,
251	                None,
252	                None,
253	                None,
254	            )?;
255	            return Ok(());
256	        };
257	        let Some(sampling_params) = sampling_params else {
258	            warn!("request {request_id} dropped: missing sampling_params");
259	            send_terminal_output(
260	                self.engine_index,
261	                output_tx,
262	                request_id,
263	                EngineCoreFinishReason::Error,
264	                None,
265	                None,
266	                None,
267	            )?;
268	            return Ok(());
269	        };
270	
271	        if let Some(unsupported) = crate::vllm::wire::unsupported_request_params(&sampling_params) {
272	            warn!("request {request_id} rejected: {unsupported}");
273	            send_terminal_output(
274	                self.engine_index,
275	                output_tx,
276	                request_id,
277	                EngineCoreFinishReason::Error,
278	                None,
279	                None,
280	                None,
281	            )?;
282	            return Ok(());
283	        }
284	        let lora_adapter = match lora_adapter_from_sampling_params(&sampling_params) {
285	            Ok(adapter) => adapter,
286	            Err(error) => {
287	                let message = error.to_string();
288	                warn!("request {request_id} rejected: {message}");
289	                send_terminal_output(
290	                    self.engine_index,
291	                    output_tx,
292	                    request_id,
293	                    EngineCoreFinishReason::Error,
294	                    Some(StopReason::Text(message)),
295	                    None,
296	                    None,
297	                )?;
298	                return Ok(());
299	            }
300	        };
301	        let kv_transfer_params = sampling_params
302	            .extra_args
303	            .as_ref()
304	            .and_then(|args| args.get("kv_transfer_params"))
305	            .cloned();
306	        let stop_sentinel_id = stop_sentinel_id(
307	            sampling_params.eos_token_id,
308	            &sampling_params.stop_token_ids,
309	        );
310	
311	        let tag: RequestTag = Arc::from(request_id.as_str());
312	        let abort_reason = Arc::new(AtomicU8::new(RequestAbortReason::None as u8));
313	        let token_tx = TokenSink::new(tag.clone(), event_tx.clone(), Arc::clone(&abort_reason));
314	        // Open the request's root span here, before submit, so its context can
315	        // travel into the scheduler as the parent of the queue/prefill/decode
316	        // spans. When tracing is off we must build a *noop* span rather than a
317	        // real one: fastrace is compiled with `enable`, so `Span::root` with a
318	        // sampled context always allocates and reports. Gating on `is_enabled()`
319	        // keeps the default (tracing-off) path free of per-request span work,
320	        // and `from_span` on a noop span yields `None` so the scheduler skips
321	        // its span work too.
322	        let trace_root = if crate::tracing_state::is_enabled() {
323	            Span::root("request", SpanContext::random())
324	                .with_property(|| ("request_id", tag.to_string()))
325	        } else {
326	            Span::noop()
327	        };
328	        let trace_parent = SpanContext::from_span(&trace_root);
329	        self.handle
330	            .submit(GenerateRequest {
331	                trace_parent,
332	                request_id: Some(request_id),
333	                queued_at_unix_s: Some(request.arrival_time),
334	                data_parallel_rank: Some(self.engine_index as usize),
335	                prompt_tokens,
336	                params: convert_sampling(&sampling_params),
337	                max_tokens: sampling_params.max_tokens as usize,
338	                lora_adapter,
339	                kv_transfer_params,
340	                token_tx,
341	                logprobs: requested_logprobs(&sampling_params),
342	                prompt_logprobs: requested_prompt_logprobs(&sampling_params),
343	            })
344	            .context("failed to submit request to scheduler")?;
345	
346	        streams.insert(
347	            tag,
348	            RequestStreamState::new(abort_reason, trace_root, stop_sentinel_id),
349	        );
350	        Ok(())
351	    }
352	}
