354	/// Per-request demux state held by the bridge loop, keyed by [`RequestTag`].
355	/// Replaces the former per-request task's locals; `first_token_*` flush onto
356	/// the request's first output, `abort_reason` is the state the scheduler's
357	/// [`TokenSink`] checks so an abort retires the request without closing the
358	/// shared channel.
359	struct RequestStreamState {
360	    first_token_events: Option<Vec<EngineCoreEvent>>,
361	    first_token_prefill_stats: Option<PrefillStats>,
362	    /// P/D handoff metadata can arrive in a burst with no token or terminal
363	    /// event, so retain it until the next output carries it to the router.
364	    kv_transfer_params: Option<serde_json::Value>,
365	    /// The vLLM text decoder removes the final token from a stop-finished
366	    /// output. Keep an EOS or explicit stop token as that removable sentinel.
367	    stop_sentinel_id: Option<u32>,
368	    abort_reason: Arc<AtomicU8>,
369	    has_emitted_tokens: bool,
370	    /// Request-lifetime root span (submit → finish). The scheduler opens
371	    /// queue/prefill/decode as children of this via the `SpanContext` passed in
372	    /// `GenerateRequest.trace_parent`, so the host-side phase breakdown is timed
373	    /// where the work actually happens (inside the scheduler), not inferred from
374	    /// event arrival at this downstream demux. `Span::noop()` when tracing is
375	    /// off. Held only for its `Drop`: dropping this state (on request completion
376	    /// or abort) ends the root span and closes the trace.
377	    #[allow(dead_code)]
378	    trace_root: Span,
379	}
380	
381	impl RequestStreamState {
382	    fn new(abort_reason: Arc<AtomicU8>, trace_root: Span, stop_sentinel_id: Option<u32>) -> Self {
383	        Self {
384	            first_token_events: None,
385	            first_token_prefill_stats: None,
386	            kv_transfer_params: None,
387	            stop_sentinel_id,
388	            abort_reason,
389	            has_emitted_tokens: false,
390	            trace_root,
391	        }
392	    }
393	
394	    fn abort(&self, reason: RequestAbortReason) {
395	        reason.store(&self.abort_reason);
396	    }
397	}
