399	/// Drain the ready burst from the shared token channel (the `first` event plus
400	/// everything already queued), bucket it per request preserving event order,
401	/// fold each request's events into at most one `EngineCoreOutput`, and ship the
402	/// whole burst as a single `EngineCoreOutputs` — collapsing what used to be N
403	/// per-request ZMQ messages per step into one.
404	fn dispatch_burst(
405	    engine_index: u32,
406	    first: (RequestTag, TokenEvent),
407	    event_rx: &mut TokenStreamReceiver,
408	    streams: &mut HashMap<RequestTag, RequestStreamState>,
409	    output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
410	) -> Result<()> {
411	    // Bucket the burst by request, keeping first-seen order so outputs are
412	    // deterministic and each request's events stay in arrival order.
413	    let mut order: Vec<RequestTag> = Vec::new();
414	    let mut buckets: HashMap<RequestTag, Vec<TokenEvent>> = HashMap::new();
415	    let mut bucket = |tag: RequestTag, event: TokenEvent| {
416	        if let Some(events) = buckets.get_mut(&tag) {
417	            events.push(event);
418	        } else {
419	            order.push(Arc::clone(&tag));
420	            buckets.insert(tag, vec![event]);
421	        }
422	    };
423	    bucket(first.0, first.1);
424	    while let Ok((tag, event)) = event_rx.try_recv() {
425	        bucket(tag, event);
426	    }
427	
428	    let mut outputs: Vec<EngineCoreOutput> = Vec::with_capacity(order.len());
429	    let mut finished_requests: BTreeSet<String> = BTreeSet::new();
430	    for tag in order {
431	        let events = buckets.remove(&tag).expect("bucket for ordered tag");
432	        // No stream entry means the request was aborted or already finished;
433	        // its late events are dropped.
434	        let Some(state) = streams.get_mut(&tag) else {
435	            continue;
436	        };
437	        let (output, terminated) = reduce_request(&tag, state, events);
438	        if let Some(output) = output {
439	            if !output.new_token_ids.is_empty() {
440	                state.has_emitted_tokens = true;
441	            }
442	            outputs.push(output);
443	        }
444	        if terminated {
445	            // Dropping the state ends both spans, closing the request trace.
446	            streams.remove(&tag);
447	            finished_requests.insert(tag.to_string());
448	        }
449	    }
450	
451	    if outputs.is_empty() {
452	        return Ok(());
453	    }
454	    send_outputs(
455	        output_tx,
456	        RequestBatchOutputs {
457	            engine_index,
458	            outputs,
459	            finished_requests: (!finished_requests.is_empty()).then_some(finished_requests),
460	            timestamp: now_secs_f64(),
461	            ..Default::default()
462	        }
463	        .into(),
464	    )
465	}
