467	/// Fold one request's events from a single burst into at most one output.
468	/// Tokens coalesce, and a trailing terminal rides the same output carrying its
469	/// finish reason; `first_token_events`/`prefill_stats` flush onto whichever
470	/// output goes first. A lone `Scheduled` (no token, no terminal) yields no
471	/// output — its metadata waits in `state` for the first real output. Returns
472	/// `(output, terminated)`.
473	fn reduce_request(
474	    request_id: &str,
475	    state: &mut RequestStreamState,
476	    events: Vec<TokenEvent>,
477	) -> (Option<EngineCoreOutput>, bool) {
478	    let mut token_ids: Vec<u32> = Vec::new();
479	    let mut positions: Vec<PositionLogprobs> = Vec::new();
480	    let mut has_logprobs = false;
481	    let mut finish_reason: Option<EngineCoreFinishReason> = None;
482	    let mut stop_reason: Option<StopReason> = None;
483	    let mut terminated = false;
484	
485	    for event in events {
486	        match event {
487	            TokenEvent::Scheduled {
488	                queued_at_unix_s,
489	                scheduled_at_unix_s,
490	                prompt_tokens,
491	                cached_tokens,
492	            } => {
493	                state.first_token_events = Some(vec![
494	                    EngineCoreEvent {
495	                        r#type: EngineCoreEventType::Queued,
496	                        timestamp: queued_at_unix_s,
497	                    },
498	                    EngineCoreEvent {
499	                        r#type: EngineCoreEventType::Scheduled,
500	                        timestamp: scheduled_at_unix_s,
501	                    },
502	                ]);
503	                // Upstream invariant: computed (actual prefill work) +
504	                // cached (prefix-cache hit) == prompt; double-counting skews
505	                // the per-source prompt token metrics.
506	                state.first_token_prefill_stats = Some(PrefillStats {
507	                    num_prompt_tokens: prompt_tokens as u32,
508	                    num_computed_tokens: prompt_tokens.saturating_sub(cached_tokens) as u32,
509	                    num_cached_tokens: cached_tokens as u32,
510	                    num_local_cached_tokens: cached_tokens as u32,
511	                    num_external_cached_tokens: 0,
512	                    num_cache_creation_tokens: 0,
513	                });
514	            }
515	            TokenEvent::Token { id, logprob } => {
516	                token_ids.push(id);
517	                if let Some(position) = to_wire_position_logprobs(id, logprob) {
518	                    has_logprobs = true;
519	                    positions.push(position);
520	                } else {
521	                    positions.push(PositionLogprobs {
522	                        entries: Vec::new(),
523	                    });
524	                }
525	            }
526	            TokenEvent::PromptTokens { .. } => {
527	                // Legacy model lines reject prompt-logprob requests at admission.
528	            }
529	            TokenEvent::KvTransfer { params } => {
530	                state.kv_transfer_params = Some(params);
531	            }
532	            TokenEvent::Finished {
533	                finish_reason: fr, ..
534	            } => {
535	                // PegaInfer suppresses EOS before emitting TokenEvents, while
536	                // vLLM's text decoder expects the terminal Stop output to
537	                // contain EOS and unconditionally removes its final token.
538	                // Without this protocol token, a speculative step that commits
539	                // [visible token, EOS] loses the visible token at the frontend.
540	                if fr == FinishReason::Stop
541	                    && let Some(stop_sentinel_id) = state.stop_sentinel_id
542	                {
543	                    token_ids.push(stop_sentinel_id);
544	                    positions.push(PositionLogprobs {
545	                        entries: Vec::new(),
546	                    });
547	                }
548	                finish_reason = Some(convert_finish_reason(fr));
549	                terminated = true;
550	            }
551	            TokenEvent::Error { message, .. } => {
552	                warn!("request {request_id} failed: {message}");
553	                finish_reason = Some(EngineCoreFinishReason::Error);
554	                stop_reason = Some(StopReason::Text(message));
555	                terminated = true;
556	            }
557	            TokenEvent::Rejected { message, .. } => {
558	                // Rejected means the request could not be admitted, not that it
559	                // completed cleanly.
560	                warn!("request {request_id} rejected: {message}");
561	                finish_reason = Some(EngineCoreFinishReason::Error);
562	                stop_reason = Some(StopReason::Text(message));
563	                terminated = true;
564	            }
565	        }
566	    }
567	
568	    if token_ids.is_empty() && !terminated {
569	        return (None, false);
570	    }
571	
572	    let logprobs = has_logprobs.then_some(MaybeWireLogprobs::Direct(Logprobs { positions }));
573	    let mut output = engine_output(
574	        request_id.to_string(),
575	        token_ids,
576	        logprobs,
577	        finish_reason,
578	        stop_reason,
579	        state.first_token_events.take(),
580	        state.first_token_prefill_stats.take(),
581	    );
582	    output.kv_transfer_params = state.kv_transfer_params.take();
583	    (Some(output), terminated)
584	}
585	
586	fn stop_sentinel_id(eos_token_id: Option<u32>, stop_token_ids: &[u32]) -> Option<u32> {
587	    eos_token_id.or_else(|| stop_token_ids.first().copied())
588	}
