590	/// vLLM `SchedulerStats` view of a load snapshot — what the frontend's
591	/// Prometheus gauges (`scheduler_running`, `scheduler_waiting`,
592	/// `kv_cache_usage`) and DP load balancer consume.
593	pub(crate) fn scheduler_stats_from(snapshot: &SchedulerMetrics) -> SchedulerStats {
594	    SchedulerStats {
595	        num_running_reqs: snapshot.num_running_reqs,
596	        num_waiting_reqs: snapshot.num_waiting_reqs,
597	        kv_cache_usage: if snapshot.kv_total_blocks == 0 {
598	            0.0
599	        } else {
600	            snapshot.kv_used_blocks as f64 / snapshot.kv_total_blocks as f64
601	        },
602	        ..SchedulerStats::default()
603	    }
604	}
