606	/// Per-interval spec-decode delta from two cumulative snapshots, in the wire
607	/// shape the frontend increments its `vllm:spec_decode_*_total` counters by (see
608	/// [`SpecDecodeCounters`] for why the transport carries totals and the wire
609	/// carries deltas).
610	fn spec_decode_delta(last: &SpecDecodeCounters, cur: &SpecDecodeCounters) -> SpecDecodingStats {
611	    let num_accepted_tokens_per_pos = cur
612	        .num_accepted_tokens_per_pos
613	        .iter()
614	        .zip(&last.num_accepted_tokens_per_pos)
615	        .map(|(cur_pos, last_pos)| cur_pos.saturating_sub(*last_pos))
616	        .take(cur.num_spec_tokens as usize)
617	        .collect();
618	    SpecDecodingStats {
619	        num_spec_tokens: cur.num_spec_tokens,
620	        num_drafts: cur.num_drafts.saturating_sub(last.num_drafts),
621	        num_draft_tokens: cur.num_draft_tokens.saturating_sub(last.num_draft_tokens),
622	        num_accepted_tokens: cur
623	            .num_accepted_tokens
624	            .saturating_sub(last.num_accepted_tokens),
625	        num_accepted_tokens_per_pos,
626	    }
627	}
628	
629	#[derive(Default)]
630	pub(crate) struct SpecDecodeTracker {
631	    last: SpecDecodeCounters,
632	}
633	
634	impl SpecDecodeTracker {
635	    /// The delta to stamp on the next outgoing batch, or `None` when nothing
636	    /// drafted. Advances the baseline, so a caller that declines to send after
637	    /// calling this drops only a no-op interval.
638	    pub(crate) fn interval(&mut self, snapshot: &SchedulerMetrics) -> Option<SpecDecodingStats> {
639	        let Some(cur) = &snapshot.spec_decode else {
640	            // Reset so a drafter loaded later diffs from zero.
641	            self.last = SpecDecodeCounters::default();
642	            return None;
643	        };
644	        let delta = spec_decode_delta(&self.last, cur);
645	        self.last = *cur;
646	        // A zero-draft interval would divide by zero in the frontend's
647	        // acceptance-rate log, and every counter moves only inside
648	        // `observe_draft`, so dropping it loses nothing.
649	        (delta.num_drafts > 0).then_some(delta)
650	    }
651	}
