653	/// Forward every scheduler load snapshot as a stats-only output batch; the
654	/// frontend records it into the shared Prometheus registry. Sends the current
655	/// snapshot up front so the gauges initialize before the first step, then one
656	/// message per watch change until shutdown. Losing either output or scheduler
657	/// load feed is fatal because keeping that engine registered would leave stale
658	/// metrics and a request-routing black hole.
659	async fn publish_scheduler_stats(
660	    engine_index: u32,
661	    mut load_rx: watch::Receiver<SchedulerMetrics>,
662	    output_tx: mpsc::UnboundedSender<EngineCoreOutputs>,
663	    shutdown: CancellationToken,
664	) -> Result<()> {
665	    let mut spec = SpecDecodeTracker::default();
666	    loop {
667	        let snapshot = *load_rx.borrow_and_update();
668	        let mut stats = scheduler_stats_from(&snapshot);
669	        stats.spec_decoding_stats = spec.interval(&snapshot);
670	        let outputs = RequestBatchOutputs {
671	            engine_index,
672	            scheduler_stats: Some(Box::new(stats)),
673	            timestamp: now_secs_f64(),
674	            ..Default::default()
675	        }
676	        .into();
677	        send_outputs(&output_tx, outputs).context("failed to publish scheduler stats")?;
678	        tokio::select! {
679	            biased;
680	            () = shutdown.cancelled() => return Ok(()),
681	            changed = load_rx.changed() => {
682	                changed.context("scheduler load feed closed")?;
683	            }
684	        }
685	    }
686	}
