688	/// The connected transport of one engine bridge: the vLLM EngineCore
689	/// handshake done, the output pump running, the stats publisher attached.
690	/// Shared by the legacy per-token bridge and the stepped bridge — everything
691	/// north of the engine data plane is identical between them.
692	struct BridgeLink {
693	    input: DealerSocket,
694	    output_tx: mpsc::UnboundedSender<EngineCoreOutputs>,
695	    child_tasks: tokio::task::JoinSet<(&'static str, Result<()>)>,
696	}
