698	#[allow(clippy::too_many_arguments)]
699	async fn connect_link(
700	    input_address: &str,
701	    output_address: &str,
702	    engine_index: u32,
703	    data_parallel_size: u32,
704	    max_model_len: u32,
705	    kv_capacity: Option<crate::engine::KvCapacity>,
706	    metrics_watch: Option<watch::Receiver<SchedulerMetrics>>,
707	    shutdown: &CancellationToken,
708	) -> Result<BridgeLink> {
709	    wait_for_ipc_endpoint(input_address, shutdown).await?;
710	    wait_for_ipc_endpoint(output_address, shutdown).await?;
711	
712	    let engine_id = EngineId::from_engine_index(
713	        u16::try_from(engine_index).context("engine_index exceeds u16 EngineId")?,
714	    );
715	    let mut socket_options = SocketOptions::default();
716	    socket_options.peer_identity(PeerIdentity::try_from(engine_id)?);
717	
718	    let mut input = DealerSocket::with_options(socket_options);
719	    input
720	        .connect(input_address)
721	        .await
722	        .with_context(|| format!("failed to connect local engine input {input_address}"))?;
723	
724	    let (num_gpu_blocks, block_size, kv_cache_size_tokens, kv_cache_max_concurrency) =
725	        match kv_capacity {
726	            Some(c) => {
727	                // vLLM single-group concurrency: blocks / ceil(max_len / block_size).
728	                let blocks_per_req = u64::from(max_model_len).div_ceil(c.block_size as u64);
729	                (
730	                    c.total_blocks as u64,
731	                    c.block_size as u64,
732	                    Some(c.total_tokens() as u64),
733	                    Some(c.total_blocks as f64 / blocks_per_req as f64),
734	                )
735	            }
736	            None => (0, 16, None, None),
737	        };
738	    let ready = EngineCoreReadyResponse {
739	        max_model_len: u64::from(max_model_len),
740	        num_gpu_blocks,
741	        block_size,
742	        dp_stats_address: None,
743	        dtype: ModelDtype::BFloat16,
744	        vllm_version: "pegainfer-local-bridge".to_string(),
745	        world_size: 1,
746	        effective_data_parallel_size: u64::from(data_parallel_size),
747	        tensor_parallel_size: 1,
748	        pipeline_parallel_size: 1,
749	        decode_context_parallel_size: 1,
750	        data_parallel_rank: engine_index,
751	        // Discovery metadata for gRPC control; HTTP completions do not admit
752	        // against these caps. Keep them above any sim concurrency we bench.
753	        max_num_seqs: 8192,
754	        max_num_batched_tokens: u64::from(max_model_len),
755	        instance_id: format!("pegainfer-local-{engine_index}"),
756	        supports_lora: false,
757	        max_loras: 0,
758	        kv_cache_size_tokens,
759	        kv_cache_max_concurrency,
760	        kv_events_config: None,
761	        weight_transfer_backend: None,
762	        enable_sleep_mode: false,
763	        supports_draft_weight_updates: false,
764	    };
765	    info!(
766	        "local engine {engine_index} KV capacity: {kv_capacity:?} -> \
767	         kv_cache_size_tokens={kv_cache_size_tokens:?} \
768	         kv_cache_max_concurrency={kv_cache_max_concurrency:?}"
769	    );
770	    input
771	        .send(ZmqMessage::from(encode_msgpack(&ready)?))
772	        .await
773	        .context("failed to send local engine ready response")?;
774	
775	    let mut output = PushSocket::new();
776	    output
777	        .connect(output_address)
778	        .await
779	        .with_context(|| format!("failed to connect local engine output {output_address}"))?;
780	
781	    let (output_tx, output_rx) = mpsc::unbounded_channel();
782	    let mut child_tasks = tokio::task::JoinSet::new();
783	    child_tasks.spawn(async move { ("output sender", output_loop(output, output_rx).await) });
784	
785	    // Legacy handle engines republish load snapshots as stats-only output
786	    // batches: their scheduler loops park when idle, so the watch cadence is
787	    // bounded. The stepped bridge passes no watch here — its driver busy-polls
788	    // (every spin would become a message), so it reads the watch at send time
789	    // and stamps stats onto the batches it already emits instead.
790	    if let Some(load_rx) = metrics_watch {
791	        let stats_output_tx = output_tx.clone();
792	        let stats_shutdown = shutdown.clone();
793	        child_tasks.spawn(async move {
794	            (
795	                "scheduler stats publisher",
796	                publish_scheduler_stats(engine_index, load_rx, stats_output_tx, stats_shutdown)
797	                    .await,
798	            )
799	        });
800	    }
801	
802	    Ok(BridgeLink {
803	        input,
804	        output_tx,
805	        child_tasks,
806	    })
807	}
808	
809	async fn output_loop(
810	    mut output: PushSocket,
811	    mut output_rx: mpsc::UnboundedReceiver<EngineCoreOutputs>,
812	) -> Result<()> {
813	    while let Some(outputs) = output_rx.recv().await {
814	        output
815	            .send(ZmqMessage::from(encode_msgpack(&outputs)?))
816	            .await
817	            .context("failed to send local engine output")?;
818	    }
819	    Ok(())
820	}
821	
822	fn send_terminal_output(
823	    engine_index: u32,
824	    output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
825	    request_id: String,
826	    finish_reason: EngineCoreFinishReason,
827	    stop_reason: Option<StopReason>,
828	    events: Option<Vec<EngineCoreEvent>>,
829	    prefill_stats: Option<PrefillStats>,
830	) -> Result<()> {
831	    send_outputs(
832	        output_tx,
833	        RequestBatchOutputs {
834	            engine_index,
835	            outputs: vec![engine_output(
836	                request_id.clone(),
837	                Vec::new(),
838	                None,
839	                Some(finish_reason),
840	                stop_reason,
841	                events,
842	                prefill_stats,
843	            )],
844	            finished_requests: Some(BTreeSet::from([request_id])),
845	            timestamp: now_secs_f64(),
846	            ..Default::default()
847	        }
848	        .into(),
849	    )
850	}
851	
852	fn send_utility_response(
853	    engine_index: u32,
854	    output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
855	    call_id: UtilityCallId,
856	    method_name: &str,
857	) -> Result<()> {
858	    let result = match method_name {
859	        "is_sleeping" | "is_paused" | "reset_prefix_cache" => rmpv::ext::to_value(false)?,
860	        "sleep" | "wake_up" | "reset_mm_cache" | "reset_encoder_cache" | "collective_rpc" => {
861	            rmpv::Value::Nil
862	        }
863	        _ => rmpv::Value::Nil,
864	    };
865	
866	    send_outputs(
867	        output_tx,
868	        UtilityCallOutput {
869	            engine_index,
870	            timestamp: now_secs_f64(),
871	            output: UtilityOutput {
872	                call_id,
873	                failure_message: None,
874	                result: Some(UtilityResultEnvelope::without_type_info(result)),
875	            },
876	        }
877	        .into(),
878	    )
879	}
880	
881	fn send_outputs(
882	    output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
883	    outputs: EngineCoreOutputs,
884	) -> Result<()> {
885	    output_tx
886	        .send(outputs)
887	        .map_err(|_| anyhow::anyhow!("local engine output channel closed"))
888	}
