890	fn engine_output(
891	    request_id: String,
892	    new_token_ids: Vec<u32>,
893	    new_logprobs: Option<MaybeWireLogprobs>,
894	    finish_reason: Option<EngineCoreFinishReason>,
895	    stop_reason: Option<StopReason>,
896	    events: Option<Vec<EngineCoreEvent>>,
897	    prefill_stats: Option<PrefillStats>,
898	) -> EngineCoreOutput {
899	    EngineCoreOutput {
900	        request_id,
901	        new_token_ids,
902	        new_logprobs,
903	        new_prompt_logprobs_tensors: None,
904	        pooling_output: None,
905	        finish_reason,
906	        stop_reason,
907	        events,
908	        kv_transfer_params: None,
909	        ec_transfer_params: None,
910	        trace_headers: None,
911	        prefill_stats,
912	        routed_experts: None,
913	        num_nans_in_logits: 0,
914	        mm_cache_miss_hashes: None,
915	        new_sampling_mask: None,
916	        spec_decode_metrics: None,
917	    }
918	}
919	
920	fn now_secs_f64() -> f64 {
921	    SystemTime::now()
922	        .duration_since(UNIX_EPOCH)
923	        .expect("system clock before unix epoch")
924	        .as_secs_f64()
925	}
926	
927	pub(crate) fn local_ipc_namespace() -> Result<PathBuf> {
928	    let base_dir =
929	        std::env::var_os("PEGAINFER_IPC_DIR").map_or_else(|| PathBuf::from("/tmp"), PathBuf::from);
930	    let uuid = uuid::Uuid::new_v4().to_string();
931	    let path = base_dir.join(format!("pgi-{}-{}", std::process::id(), &uuid[..8]));
932	    std::fs::create_dir_all(&path)
933	        .with_context(|| format!("failed to create IPC namespace {}", path.display()))?;
934	    Ok(path)
935	}
