937	pub(crate) fn ipc_endpoint(namespace: &Path, name: &str) -> String {
938	    format!("ipc://{}", namespace.join(name).to_string_lossy())
939	}
940	
941	async fn wait_for_ipc_endpoint(address: &str, shutdown: &CancellationToken) -> Result<()> {
942	    let Some(path) = address.strip_prefix("ipc://") else {
943	        return Ok(());
944	    };
945	    let path = Path::new(path);
946	    loop {
947	        if path.exists() {
948	            return Ok(());
949	        }
950	        tokio::select! {
951	            () = shutdown.cancelled() => bail!("shutdown before IPC endpoint appeared"),
952	            () = tokio::time::sleep(Duration::from_millis(20)) => {}
953	        }
954	    }
955	}
