185	    /// Stats for an outgoing batch; the spec delta runs from the last batch
186	    /// stamped, not the last step run.
187	    fn stats(&self, spec: &mut SpecDecodeTracker) -> SchedulerStats {
188	        let snapshot = self.scheduler.metrics();
189	        let mut stats = scheduler_stats_from(&snapshot);
190	        stats.spec_decoding_stats = spec.interval(&snapshot);
191	        stats
192	    }
193	
194	    fn dispatch_step(
195	        &self,
196	        step: StepOutputs,
197	        anchor: &UnixAnchor,
198	        streams: &mut HashMap<RequestId, SteppedStream>,
199	        names: &mut HashMap<String, RequestId>,
200	        spec: &mut SpecDecodeTracker,
201	        output_tx: &tokio::sync::mpsc::UnboundedSender<
202	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
203	        >,
204	    ) -> Result<()> {
205	        let mut outputs: Vec<EngineCoreOutput> = Vec::with_capacity(step.updates.len());
206	        let mut finished_requests: BTreeSet<String> = BTreeSet::new();
207	        for update in step.updates {
208	            // No stream entry means the request was aborted or already
209	            // finished; late updates (including retire-window drop bombs) are
210	            // dropped.
211	            let Some(state) = streams.get_mut(&update.id) else {
212	                continue;
213	            };
214	            let id = update.id;
215	            let (output, terminated) = reduce_update(state, update, anchor);
216	            if let Some(output) = output {
217	                outputs.push(output);
218	            }
219	            if terminated {
220	                // Dropping the state ends the root span, closing the trace.
221	                let state = streams.remove(&id).expect("terminated stream present");
222	                names.remove(&state.request_id);
223	                finished_requests.insert(state.request_id);
224	            }
225	        }
226	
227	        if outputs.is_empty() {
228	            // A drafted step with no batch to ride would strand its increment
229	            // until the next batch, which may never come.
230	            let stats = self.stats(spec);
231	            if stats.spec_decoding_stats.is_some() {
232	                send_outputs(
233	                    output_tx,
234	                    RequestBatchOutputs {
235	                        engine_index: self.engine_index,
236	                        scheduler_stats: Some(Box::new(stats)),
237	                        timestamp: now_secs_f64(),
238	                        ..Default::default()
239	                    }
240	                    .into(),
241	                )?;
242	            }
243	            return Ok(());
244	        }
245	        // The cell already holds this step's snapshot (the driver publishes
246	        // load before committing the step), so the batch carries stats that
247	        // match its own tokens — a finishing batch reports the drained state
248	        // and the gauges settle instead of freezing at the last busy value.
249	        send_outputs(
250	            output_tx,
251	            RequestBatchOutputs {
252	                engine_index: self.engine_index,
253	                outputs,
254	                finished_requests: (!finished_requests.is_empty()).then_some(finished_requests),
255	                scheduler_stats: Some(Box::new(self.stats(spec))),
256	                timestamp: now_secs_f64(),
257	            }
258	            .into(),
259	        )
260	    }
261	
262	    fn handle_message(
263	        &self,
264	        message: ZmqMessage,
265	        streams: &mut HashMap<RequestId, SteppedStream>,
266	        names: &mut HashMap<String, RequestId>,
267	        output_tx: &tokio::sync::mpsc::UnboundedSender<
268	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
269	        >,
270	    ) -> Result<()> {
271	        let frames = message.into_vec();
272	        if frames.len() != 2 {
273	            bail!(
274	                "expected 2 local engine request frames, got {}",
275	                frames.len()
276	            );
277	        }
278	
279	        match frames[0].as_ref() {
280	            ty if ty == EngineCoreRequestType::Add.to_frame().as_ref() => {
281	                let request: EngineCoreRequest =
282	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
283	                self.start_request(request, streams, names, output_tx)
284	            }
285	            ty if ty == EngineCoreRequestType::Abort.to_frame().as_ref() => {
286	                let request_ids: Vec<String> =
287	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
288	                for request_id in request_ids {
289	                    // Drop our state first, then flip the abort flag (whose
290	                    // `Release` store orders after the removal); the
291	                    // scheduler's next touch retires the request, and any
292	                    // update already in flight finds no stream entry.
293	                    let Some(id) = names.remove(&request_id) else {
294	                        continue;
295	                    };
296	                    if let Some(state) = streams.remove(&id) {
297	                        state.control.abort();
298	                    }
299	                }
300	                Ok(())
301	            }
302	            ty if ty == EngineCoreRequestType::Utility.to_frame().as_ref() => {
303	                let (_client_index, call_id, method_name, _args): (
304	                    u32,
305	                    UtilityCallId,
306	                    String,
307	                    rmpv::Value,
308	                ) = rmp_serde::from_slice(&frames[1])?;
309	                send_utility_response(self.engine_index, output_tx, call_id, &method_name)
310	            }
311	            other => bail!("unsupported local engine request type frame: {other:?}"),
312	        }
313	    }
314	
315	    fn start_request(
316	        &self,
317	        request: EngineCoreRequest,
318	        streams: &mut HashMap<RequestId, SteppedStream>,
319	        names: &mut HashMap<String, RequestId>,
320	        output_tx: &tokio::sync::mpsc::UnboundedSender<
321	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
322	        >,
323	    ) -> Result<()> {
324	        let EngineCoreRequest {
325	            request_id,
326	            prompt_token_ids,
327	            sampling_params,
328	            ..
329	        } = request;
330	        let Some(prompt_tokens) = prompt_token_ids else {
331	            warn!("request {request_id} dropped: missing prompt_token_ids");
332	            return send_terminal_output(
333	                self.engine_index,
334	                output_tx,
335	                request_id,
336	                EngineCoreFinishReason::Error,
337	                None,
338	                None,
339	                None,
340	            );
341	        };
342	        let Some(sampling_params) = sampling_params else {
343	            warn!("request {request_id} dropped: missing sampling_params");
344	            return send_terminal_output(
345	                self.engine_index,
346	                output_tx,
347	                request_id,
348	                EngineCoreFinishReason::Error,
349	                None,
350	                None,
351	                None,
352	            );
353	        };
354	
355	        if let Some(unsupported) = crate::vllm::wire::unsupported_request_params(&sampling_params) {
356	            warn!("request {request_id} rejected: {unsupported}");
357	            return send_terminal_output(
358	                self.engine_index,
359	                output_tx,
360	                request_id,
361	                EngineCoreFinishReason::Error,
362	                None,
363	                None,
364	                None,
365	            );
366	        }
367	        let lora_adapter = match lora_adapter_from_sampling_params(&sampling_params) {
368	            Ok(adapter) => adapter,
369	            Err(error) => {
370	                let message = error.to_string();
371	                warn!("request {request_id} rejected: {message}");
372	                return send_terminal_output(
373	                    self.engine_index,
374	                    output_tx,
375	                    request_id,
376	                    EngineCoreFinishReason::Error,
377	                    Some(StopReason::Text(message)),
378	                    None,
379	                    None,
380	                );
381	            }
382	        };
383	        let kv_transfer_params = sampling_params
384	            .extra_args
385	            .as_ref()
386	            .and_then(|args| args.get("kv_transfer_params"))
387	            .cloned();
388	        let stop_sentinel_id = stop_sentinel_id(
389	            sampling_params.eos_token_id,
390	            &sampling_params.stop_token_ids,
391	        );
392	
393	        // Open the request's root span before submit so its context travels
394	        // into the scheduler as the parent of the queue/prefill/decode spans;
395	        // noop (no allocation, `from_span` yields `None`) when tracing is off.
396	        let trace_root = if crate::tracing_state::is_enabled() {
397	            Span::root("request", SpanContext::random())
398	                .with_property(|| ("request_id", request_id.clone()))
399	        } else {
400	            Span::noop()
401	        };
402	        let trace_parent = SpanContext::from_span(&trace_root);
403	        let control = self.scheduler.submit(Request {
404	            prompt_tokens,
405	            params: convert_sampling(&sampling_params),
406	            max_tokens: sampling_params.max_tokens as usize,
407	            lora_adapter,
408	            kv_transfer_params,
409	            logprobs: requested_logprobs(&sampling_params),
410	            prompt_logprobs: requested_prompt_logprobs(&sampling_params),
411	            trace_parent,
412	            client_label: Some(Arc::from(request_id.as_str())),
413	        });
414	
415	        names.insert(request_id.clone(), control.id());
416	        streams.insert(
417	            control.id(),
418	            SteppedStream::new(request_id, control, trace_root, stop_sentinel_id),
419	        );
420	        Ok(())
421	    }
422	}
