677	        assert_eq!(
678	            output.stop_reason,
679	            Some(StopReason::Text(
680	                "this engine does not support kv_transfer".into()
681	            ))
682	        );
683	        assert!(
684	            output.prefill_stats.is_none(),
685	            "a request refused while queued did no prefill"
686	        );
687	    }
688	
689	    fn bridge(scheduler: SchedulerHandle) -> SteppedEngineBridge {
690	        SteppedEngineBridge {
691	            input_address: String::new(),
692	            output_address: String::new(),
693	            scheduler,
694	            kv_capacity: None,
695	            max_model_len: 128,
696	            engine_index: 0,
697	            data_parallel_size: 1,
698	        }
699	    }
700	
701	    fn wire_request(completion: Option<i32>, prompt: Option<i32>) -> EngineCoreRequest {
702	        let mut params = EngineCoreSamplingParams::for_test();
703	        params.logprobs = completion;
704	        params.prompt_logprobs = prompt;
705	        EngineCoreRequest {
706	            request_id: "logprobs".into(),
707	            prompt_token_ids: Some(vec![9, 8]),
708	            sampling_params: Some(params),
709	            ..Default::default()
710	        }
711	    }
712	
713	    #[test]
714	    fn negative_engine_core_logprob_counts_are_rejected_before_submission() {
715	        for (completion, prompt) in [(Some(-2), None), (None, Some(-2))] {
716	            let (handle, backend) = scheduler_pair();
717	            let bridge = bridge(handle);
718	            let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
719	            let mut streams = HashMap::new();
720	            bridge
721	                .start_request(
722	                    wire_request(completion, prompt),
723	                    &mut streams,
724	                    &mut HashMap::new(),
725	                    &tx,
726	                )
727	                .unwrap();
728	            assert!(streams.is_empty());
729	            assert!(backend.submissions.try_recv().is_err());
730	            let EngineCoreOutputs::RequestBatch(batch) = rx.try_recv().unwrap() else {
731	                panic!("expected a terminal request batch");
732	            };
733	            assert_eq!(batch.outputs.len(), 1);
734	            assert_eq!(batch.outputs[0].request_id, "logprobs");
735	            assert_eq!(
736	                batch.outputs[0].finish_reason,
737	                Some(EngineCoreFinishReason::Error)
738	            );
739	        }
740	    }
741	
742	    fn prompt_update(id: RequestId, score: Option<TokenLogprob>) -> RequestUpdate {
743	        let mut update = RequestUpdate::empty(id);
744	        update.prompt_echo = Some(PromptEcho {
745	            ids: vec![9, 8],
746	            logprobs: vec![None, score],
747	        });
748	        update
749	    }
750	
751	    #[test]
752	    fn prompt_only_flushes_and_malformed_prompt_aborts_its_request() {
753	        let (handle, mut backend) = scheduler_pair();
754	        let bridge = bridge(handle);
755	        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel();
756	        let mut streams = HashMap::new();
757	        bridge
758	            .start_request(
759	                wire_request(Some(0), Some(2)),
760	                &mut streams,
761	                &mut HashMap::new(),
762	                &tx,
763	            )
764	            .unwrap();
765	        let queued = backend
766	            .ledger
767	            .register(backend.submissions.try_recv().unwrap());
768	        assert_eq!(queued.request.logprobs, Some(0));
769	        assert_eq!(queued.request.prompt_logprobs, Some(2));
770	        let state = streams.get_mut(&queued.id).unwrap();
771	        let update = prompt_update(
772	            queued.id,
773	            Some(TokenLogprob {
774	                rank: 1,
775	                logprob: -0.5,
776	                top_logprobs: Vec::new(),
777	            }),
778	        );
779	        let (output, terminated) = reduce_update(state, update, &UnixAnchor::now());
780	        assert!(!terminated);
781	        let output = output.expect("prompt-only output must flush");
782	        assert!(output.new_token_ids.is_empty());
783	        assert!(output.new_prompt_logprobs_tensors.is_some());
784	        let malformed = prompt_update(queued.id, None);
785	        let (output, terminated) = reduce_update(state, malformed, &UnixAnchor::now());
786	        assert!(terminated);
787	        assert_eq!(
788	            output.unwrap().finish_reason,
789	            Some(EngineCoreFinishReason::Error)
790	        );
791	        assert!(backend.ledger.is_aborted(queued.id));
792	    }
793	}
